import React, { useState, useEffect } from 'react';

const IMG_DATA = "";

const INSTRUCTIONS = [
  { type: 'header', text: '> LOADING MISSION BRIEFING...' },
  { type: 'pause', duration: 500 },
  { type: 'header', text: '> GORBOY TACTICAL MANUAL v2.0' },
  { type: 'pause', duration: 300 },
  { type: 'divider' },
  { type: 'section', text: '[OBJECTIVE]' },
  { type: 'text', text: 'Navigate through hostile zones and eliminate all enemy targets. Collect power-ups to enhance your abilities and reach the extraction point before time runs out.' },
  { type: 'pause', duration: 200 },
  { type: 'divider' },
  { type: 'section', text: '[MOVEMENT]' },
  { type: 'text', text: 'Use WASD or ARROW KEYS to move your character. Hold SHIFT for precision movement in tight spaces.' },
  { type: 'pause', duration: 200 },
  { type: 'divider' },
  { type: 'section', text: '[COMBAT]' },
  { type: 'text', text: 'Press Z or J to fire your primary weapon. Press X or K to activate your shield. Build combos by defeating enemies in quick succession.' },
  { type: 'pause', duration: 200 },
  { type: 'divider' },
  { type: 'section', text: '[POWER-UPS]' },
  { type: 'list', items: [
    '◆ HEALTH PACK - Restores 25% HP',
    '◆ RAPID FIRE - 2x attack speed for 10s',
    '◆ SHIELD BOOST - Temporary invincibility',
    '◆ SCORE MULT - 2x points for 30s',
  ]},
  { type: 'pause', duration: 200 },
  { type: 'divider' },
  { type: 'section', text: '[TIPS]' },
  { type: 'text', text: 'Watch your ammo count. Reload during safe moments. Enemy patterns repeat - learn them. Boss weak points flash when vulnerable.' },
  { type: 'pause', duration: 300 },
  { type: 'divider' },
  { type: 'success', text: '> BRIEFING COMPLETE. GOOD LUCK, SOLDIER.' },
  { type: 'blink', text: '> PRESS START WHEN READY_' },
];

export default function GorboyHowToPlay() {
  const [displayedLines, setDisplayedLines] = useState([]);
  const [currentLineIndex, setCurrentLineIndex] = useState(0);
  const [currentCharIndex, setCurrentCharIndex] = useState(0);
  const [isTyping, setIsTyping] = useState(true);

  useEffect(() => {
    if (currentLineIndex >= INSTRUCTIONS.length) {
      setIsTyping(false);
      return;
    }

    const currentInstruction = INSTRUCTIONS[currentLineIndex];

    if (currentInstruction.type === 'pause') {
      const timeout = setTimeout(() => {
        setCurrentLineIndex(prev => prev + 1);
      }, currentInstruction.duration);
      return () => clearTimeout(timeout);
    }

    if (currentInstruction.type === 'divider') {
      setDisplayedLines(prev => [...prev, { type: 'divider' }]);
      setCurrentLineIndex(prev => prev + 1);
      return;
    }

    if (currentInstruction.type === 'list') {
      setDisplayedLines(prev => [...prev, { type: 'list', items: currentInstruction.items }]);
      setCurrentLineIndex(prev => prev + 1);
      return;
    }

    const text = currentInstruction.text;
    
    if (currentCharIndex < text.length) {
      const timeout = setTimeout(() => {
        setDisplayedLines(prev => {
          const newLines = [...prev];
          const lastLineIndex = newLines.length - 1;
          
          if (lastLineIndex >= 0 && newLines[lastLineIndex].lineIndex === currentLineIndex) {
            newLines[lastLineIndex] = {
              ...newLines[lastLineIndex],
              text: text.substring(0, currentCharIndex + 1),
            };
          } else {
            newLines.push({
              type: currentInstruction.type,
              text: text.substring(0, currentCharIndex + 1),
              lineIndex: currentLineIndex,
            });
          }
          return newLines;
        });
        setCurrentCharIndex(prev => prev + 1);
      }, currentInstruction.type === 'header' || currentInstruction.type === 'section' ? 30 : 15);
      
      return () => clearTimeout(timeout);
    } else {
      setCurrentCharIndex(0);
      setCurrentLineIndex(prev => prev + 1);
    }
  }, [currentLineIndex, currentCharIndex]);

  const resetAnimation = () => {
    setDisplayedLines([]);
    setCurrentLineIndex(0);
    setCurrentCharIndex(0);
    setIsTyping(true);
  };

  const skipAnimation = () => {
    const allLines = INSTRUCTIONS.filter(i => i.type !== 'pause').map((instruction, idx) => ({
      type: instruction.type,
      text: instruction.text,
      items: instruction.items,
      lineIndex: idx,
    }));
    setDisplayedLines(allLines);
    setCurrentLineIndex(INSTRUCTIONS.length);
    setIsTyping(false);
  };

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: '#0a0a0a',
      fontFamily: '"Press Start 2P", "Courier New", monospace',
      overflow: 'hidden',
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&family=Silkscreen:wght@400;700&display=swap');
        
        @keyframes blink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
        
        @keyframes glow {
          0%, 100% { text-shadow: 0 0 10px currentColor, 0 0 20px currentColor; }
          50% { text-shadow: 0 0 20px currentColor, 0 0 40px currentColor, 0 0 60px currentColor; }
        }
        
        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-5px); }
        }
        
        @keyframes gridMove {
          0% { transform: rotateX(60deg) translateY(0); }
          100% { transform: rotateX(60deg) translateY(50px); }
        }
        
        @keyframes cursor {
          0%, 50% { border-right-color: #00ff88; }
          51%, 100% { border-right-color: transparent; }
        }
        
        .scanlines::before {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: repeating-linear-gradient(
            0deg,
            rgba(0, 0, 0, 0.1) 0px,
            rgba(0, 0, 0, 0.1) 1px,
            transparent 1px,
            transparent 2px
          );
          pointer-events: none;
          z-index: 10;
        }
        
        .perspective-grid-container {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          height: 60%;
          perspective: 400px;
          perspective-origin: 50% 0%;
          overflow: hidden;
          mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
          -webkit-mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
        }
        
        .perspective-grid {
          position: absolute;
          top: 0;
          left: -50%;
          width: 200%;
          height: 300%;
          background-image: 
            linear-gradient(rgba(0,255,136,0.4) 2px, transparent 2px),
            linear-gradient(90deg, rgba(0,255,136,0.4) 2px, transparent 2px);
          background-size: 50px 50px;
          transform-origin: center top;
          animation: gridMove 2s linear infinite;
        }
        
        .horizon-glow {
          position: absolute;
          bottom: 40%;
          left: 0;
          right: 0;
          height: 200px;
          background: radial-gradient(ellipse 80% 50% at 50% 100%, rgba(0,255,136,0.15) 0%, transparent 70%);
          pointer-events: none;
        }
        
        .pixel-btn {
          image-rendering: pixelated;
          transition: all 0.1s ease;
        }
        
        .pixel-btn:hover {
          transform: scale(1.05);
          filter: brightness(1.2);
        }
        
        .pixel-btn:active {
          transform: scale(0.95);
        }
        
        .terminal-content {
          scrollbar-width: thin;
          scrollbar-color: #00ff88 #001a0a;
        }
        
        .terminal-content::-webkit-scrollbar {
          width: 8px;
        }
        
        .terminal-content::-webkit-scrollbar-track {
          background: #001a0a;
        }
        
        .terminal-content::-webkit-scrollbar-thumb {
          background: #00ff88;
        }
        
        .typing-cursor {
          display: inline-block;
          width: 10px;
          height: 18px;
          background: #00ff88;
          margin-left: 2px;
          animation: blink 0.8s infinite;
        }
      `}</style>

      <div style={{
        position: 'relative',
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #0a0a0a 0%, #0a1a0f 40%, #0f2a1a 100%)',
        overflow: 'hidden',
      }} className="scanlines">
        
        {/* 3D Perspective Grid */}
        <div className="perspective-grid-container">
          <div className="perspective-grid" />
        </div>
        
        {/* Horizon Glow */}
        <div className="horizon-glow" />
        
        {/* Background Image */}
        <div style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          width: '100%',
          maxWidth: '600px',
          opacity: 0.35,
          mixBlendMode: 'lighten',
        }}>
          <img 
            src={`data:image/webp;base64,${IMG_DATA}`}
            alt="GORBOY Dark"
            style={{ width: '100%', height: 'auto', mixBlendMode: 'lighten' }}
          />
        </div>
        
        {/* Main Content */}
        <div style={{
          position: 'relative',
          zIndex: 5,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          padding: '30px 20px',
          maxWidth: '600px',
          margin: '0 auto',
        }}>
          {/* Header */}
          <div style={{
            textAlign: 'center',
            marginBottom: '20px',
          }}>
            <div style={{
              fontFamily: '"VT323", monospace',
              fontSize: '14px',
              color: '#00ff88',
              letterSpacing: '12px',
              marginBottom: '8px',
              opacity: 0.7,
            }}>
              GORBOY://MANUAL
            </div>
            <h1 style={{
              fontFamily: '"Press Start 2P", monospace',
              fontSize: 'clamp(20px, 5vw, 32px)',
              color: '#00ff88',
              textShadow: '0 0 20px rgba(0,255,136,0.5), 0 0 40px rgba(0,255,136,0.3)',
              margin: 0,
              letterSpacing: '4px',
              animation: 'glow 3s ease-in-out infinite',
            }}>
              HOW TO PLAY
            </h1>
          </div>

          {/* Terminal Window */}
          <div style={{
            backgroundColor: 'rgba(0,20,10,0.9)',
            border: '2px solid #00ff88',
            width: '100%',
            boxShadow: '0 0 30px rgba(0,255,136,0.2), inset 0 0 60px rgba(0,0,0,0.5)',
            marginBottom: '20px',
          }}>
            {/* Terminal Header */}
            <div style={{
              backgroundColor: '#00ff88',
              padding: '8px 15px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
            }}>
              <span style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '8px',
                color: '#001a0a',
              }}>
                TACTICAL_TERMINAL
              </span>
              <div style={{ display: 'flex', gap: '6px' }}>
                <div style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: '#001a0a', opacity: 0.3 }} />
                <div style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: '#001a0a', opacity: 0.3 }} />
                <div style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: '#001a0a' }} />
              </div>
            </div>
            
            {/* Terminal Content */}
            <div 
              className="terminal-content"
              style={{ 
                padding: '20px',
                height: '350px',
                overflowY: 'auto',
              }}
            >
              {displayedLines.map((line, idx) => {
                if (line.type === 'divider') {
                  return (
                    <div key={idx} style={{
                      fontFamily: '"VT323", monospace',
                      fontSize: '16px',
                      color: '#00aa55',
                      margin: '10px 0',
                      opacity: 0.5,
                    }}>
                      ════════════════════════════════════
                    </div>
                  );
                }
                
                if (line.type === 'list') {
                  return (
                    <div key={idx} style={{ margin: '10px 0' }}>
                      {line.items.map((item, itemIdx) => (
                        <div key={itemIdx} style={{
                          fontFamily: '"VT323", monospace',
                          fontSize: '18px',
                          color: '#00ff88',
                          padding: '4px 0 4px 15px',
                        }}>
                          {item}
                        </div>
                      ))}
                    </div>
                  );
                }

                let color = '#00ff88';
                let fontSize = '18px';
                let marginBottom = '8px';
                
                if (line.type === 'header') {
                  color = '#00ff88';
                  fontSize = '16px';
                  marginBottom = '12px';
                } else if (line.type === 'section') {
                  color = '#00ffcc';
                  fontSize = '16px';
                  marginBottom = '8px';
                } else if (line.type === 'success') {
                  color = '#00ff88';
                  fontSize = '16px';
                } else if (line.type === 'blink') {
                  return (
                    <div key={idx} style={{
                      fontFamily: '"VT323", monospace',
                      fontSize: '18px',
                      color: '#00ff88',
                      marginTop: '15px',
                      animation: 'blink 1.5s infinite',
                    }}>
                      {line.text}
                    </div>
                  );
                } else {
                  color = '#00aa55';
                }

                return (
                  <div key={idx} style={{
                    fontFamily: '"VT323", monospace',
                    fontSize,
                    color,
                    marginBottom,
                    lineHeight: '1.4',
                  }}>
                    {line.text}
                    {isTyping && idx === displayedLines.length - 1 && (
                      <span className="typing-cursor" />
                    )}
                  </div>
                );
              })}
              
              {displayedLines.length === 0 && isTyping && (
                <span className="typing-cursor" />
              )}
            </div>
          </div>

          {/* Action Buttons */}
          <div style={{
            display: 'flex',
            gap: '15px',
            flexWrap: 'wrap',
            justifyContent: 'center',
          }}>
            {isTyping ? (
              <button
                onClick={skipAnimation}
                className="pixel-btn"
                style={{
                  fontFamily: '"Press Start 2P", monospace',
                  fontSize: '10px',
                  padding: '12px 20px',
                  backgroundColor: 'transparent',
                  color: '#00ff88',
                  border: '2px solid #00ff88',
                  cursor: 'pointer',
                  boxShadow: '0 0 10px rgba(0,255,136,0.3)',
                }}
              >
                [SKIP]
              </button>
            ) : (
              <button
                onClick={resetAnimation}
                className="pixel-btn"
                style={{
                  fontFamily: '"Press Start 2P", monospace',
                  fontSize: '10px',
                  padding: '12px 20px',
                  backgroundColor: 'transparent',
                  color: '#00ff88',
                  border: '2px solid #00ff88',
                  cursor: 'pointer',
                  boxShadow: '0 0 10px rgba(0,255,136,0.3)',
                }}
              >
                [REPLAY]
              </button>
            )}
            <button
              className="pixel-btn"
              style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '10px',
                padding: '12px 20px',
                backgroundColor: '#00ff88',
                color: '#001a0a',
                border: '2px solid #00ff88',
                cursor: 'pointer',
                boxShadow: '0 0 10px rgba(0,255,136,0.3)',
                animation: 'float 3s ease-in-out infinite',
              }}
            >
              [START]
            </button>
            <button
              className="pixel-btn"
              style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '10px',
                padding: '12px 20px',
                backgroundColor: 'transparent',
                color: '#00ff88',
                border: '2px solid #00ff88',
                cursor: 'pointer',
                boxShadow: '0 0 10px rgba(0,255,136,0.3)',
              }}
            >
              [BACK]
            </button>
          </div>

          {/* Corner Decorations */}
          <div style={{
            position: 'absolute',
            top: '20px',
            left: '20px',
            width: '30px',
            height: '30px',
            borderTop: '2px solid #00ff88',
            borderLeft: '2px solid #00ff88',
            opacity: 0.5,
          }} />
          <div style={{
            position: 'absolute',
            bottom: '20px',
            right: '20px',
            width: '30px',
            height: '30px',
            borderBottom: '2px solid #00ff88',
            borderRight: '2px solid #00ff88',
            opacity: 0.5,
          }} />

          {/* Footer */}
          <div style={{
            marginTop: '20px',
            fontFamily: '"VT323", monospace',
            fontSize: '12px',
            color: '#00aa55',
            letterSpacing: '3px',
            textAlign: 'center',
          }}>
            SYS.ID: GOR-8BIT-2025 | MANUAL v1.0
          </div>
        </div>
      </div>
    </div>
  );
}
