import React, { useState } from 'react';

const IMG_DATA = "";

export default function GorboySettings() {
  const [settings, setSettings] = useState({
    volume: 80,
    brightness: 70,
    contrast: 50,
    scanlines: true,
    screenShake: true,
    colorMode: 'classic',
    difficulty: 'normal',
    language: 'en',
    autoSave: true,
    rumble: true,
  });

  const updateSetting = (key, value) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const SliderControl = ({ label, value, onChange, min = 0, max = 100 }) => (
    <div style={{ marginBottom: '20px' }}>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        marginBottom: '8px',
      }}>
        <span style={{
          fontFamily: '"VT323", monospace',
          fontSize: '18px',
          color: '#00ff88',
        }}>
          {label}
        </span>
        <span style={{
          fontFamily: '"VT323", monospace',
          fontSize: '18px',
          color: '#00aa55',
        }}>
          {value}%
        </span>
      </div>
      <div style={{
        position: 'relative',
        height: '20px',
        backgroundColor: 'rgba(0,40,20,0.8)',
        border: '2px solid #00aa55',
      }}>
        <div style={{
          position: 'absolute',
          top: '2px',
          left: '2px',
          bottom: '2px',
          width: `calc(${value}% - 4px)`,
          backgroundColor: '#00ff88',
          boxShadow: '0 0 10px rgba(0,255,136,0.5)',
          transition: 'width 0.1s ease',
        }} />
        <input
          type="range"
          min={min}
          max={max}
          value={value}
          onChange={(e) => onChange(parseInt(e.target.value))}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            opacity: 0,
            cursor: 'pointer',
          }}
        />
      </div>
    </div>
  );

  const ToggleControl = ({ label, value, onChange }) => (
    <div style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '15px',
      padding: '10px 0',
      borderBottom: '1px solid rgba(0,255,136,0.2)',
    }}>
      <span style={{
        fontFamily: '"VT323", monospace',
        fontSize: '18px',
        color: '#00ff88',
      }}>
        {label}
      </span>
      <button
        onClick={() => onChange(!value)}
        className="pixel-btn"
        style={{
          fontFamily: '"Press Start 2P", monospace',
          fontSize: '8px',
          padding: '8px 16px',
          backgroundColor: value ? '#00ff88' : 'transparent',
          color: value ? '#001a0a' : '#00aa55',
          border: '2px solid #00ff88',
          cursor: 'pointer',
          minWidth: '70px',
        }}
      >
        {value ? 'ON' : 'OFF'}
      </button>
    </div>
  );

  const SelectControl = ({ label, value, options, onChange }) => (
    <div style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '15px',
      padding: '10px 0',
      borderBottom: '1px solid rgba(0,255,136,0.2)',
    }}>
      <span style={{
        fontFamily: '"VT323", monospace',
        fontSize: '18px',
        color: '#00ff88',
      }}>
        {label}
      </span>
      <div style={{ display: 'flex', gap: '5px' }}>
        {options.map((opt) => (
          <button
            key={opt.value}
            onClick={() => onChange(opt.value)}
            className="pixel-btn"
            style={{
              fontFamily: '"Press Start 2P", monospace',
              fontSize: '6px',
              padding: '6px 10px',
              backgroundColor: value === opt.value ? '#00ff88' : 'transparent',
              color: value === opt.value ? '#001a0a' : '#00aa55',
              border: '2px solid ' + (value === opt.value ? '#00ff88' : '#00aa55'),
              cursor: 'pointer',
            }}
          >
            {opt.label}
          </button>
        ))}
      </div>
    </div>
  );

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: '#0a0a0a',
      fontFamily: '"Press Start 2P", "Courier New", monospace',
      overflow: 'hidden',
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&family=Silkscreen:wght@400;700&display=swap');
        
        @keyframes blink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
        
        @keyframes glow {
          0%, 100% { text-shadow: 0 0 10px currentColor, 0 0 20px currentColor; }
          50% { text-shadow: 0 0 20px currentColor, 0 0 40px currentColor, 0 0 60px currentColor; }
        }
        
        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-5px); }
        }
        
        @keyframes gridMove {
          0% { transform: rotateX(60deg) translateY(0); }
          100% { transform: rotateX(60deg) translateY(50px); }
        }
        
        @keyframes rotate {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        
        .scanlines::before {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: repeating-linear-gradient(
            0deg,
            rgba(0, 0, 0, 0.1) 0px,
            rgba(0, 0, 0, 0.1) 1px,
            transparent 1px,
            transparent 2px
          );
          pointer-events: none;
          z-index: 10;
        }
        
        .perspective-grid-container {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          height: 60%;
          perspective: 400px;
          perspective-origin: 50% 0%;
          overflow: hidden;
          mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
          -webkit-mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
        }
        
        .perspective-grid {
          position: absolute;
          top: 0;
          left: -50%;
          width: 200%;
          height: 300%;
          background-image: 
            linear-gradient(rgba(0,255,136,0.4) 2px, transparent 2px),
            linear-gradient(90deg, rgba(0,255,136,0.4) 2px, transparent 2px);
          background-size: 50px 50px;
          transform-origin: center top;
          animation: gridMove 2s linear infinite;
        }
        
        .horizon-glow {
          position: absolute;
          bottom: 40%;
          left: 0;
          right: 0;
          height: 200px;
          background: radial-gradient(ellipse 80% 50% at 50% 100%, rgba(0,255,136,0.15) 0%, transparent 70%);
          pointer-events: none;
        }
        
        .gorboy-bg-image {
          mix-blend-mode: lighten;
        }
        
        .pixel-btn {
          image-rendering: pixelated;
          transition: all 0.1s ease;
        }
        
        .pixel-btn:hover {
          transform: scale(1.05);
          filter: brightness(1.2);
        }
        
        .pixel-btn:active {
          transform: scale(0.95);
        }
        
        .settings-section {
          margin-bottom: '20px';
        }
        
        .gear-icon {
          animation: rotate 10s linear infinite;
        }
      `}</style>

      <div style={{
        position: 'relative',
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #0a0a0a 0%, #0a1a0f 40%, #0f2a1a 100%)',
        overflow: 'hidden',
      }} className="scanlines">
        
        {/* 3D Perspective Grid */}
        <div className="perspective-grid-container">
          <div className="perspective-grid" />
        </div>
        
        {/* Horizon Glow */}
        <div className="horizon-glow" />
        
        {/* Background Image */}
        <div style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          width: '100%',
          maxWidth: '600px',
          opacity: 0.35,
          mixBlendMode: 'lighten',
        }}>
          <img 
            src={`data:image/webp;base64,${IMG_DATA}`}
            alt="GORBOY Dark"
            style={{ width: '100%', height: 'auto', mixBlendMode: 'lighten' }}
          />
        </div>
        
        {/* Main Content */}
        <div style={{
          position: 'relative',
          zIndex: 5,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          padding: '30px 20px',
          maxWidth: '500px',
          margin: '0 auto',
        }}>
          {/* Header */}
          <div style={{
            textAlign: 'center',
            marginBottom: '25px',
          }}>
            <div style={{
              fontFamily: '"VT323", monospace',
              fontSize: '14px',
              color: '#00ff88',
              letterSpacing: '12px',
              marginBottom: '8px',
              opacity: 0.7,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '10px',
            }}>
              <span className="gear-icon" style={{ fontSize: '16px' }}>⚙</span>
              GORBOY://CONFIG
              <span className="gear-icon" style={{ fontSize: '16px' }}>⚙</span>
            </div>
            <h1 style={{
              fontFamily: '"Press Start 2P", monospace',
              fontSize: 'clamp(20px, 5vw, 32px)',
              color: '#00ff88',
              textShadow: '0 0 20px rgba(0,255,136,0.5), 0 0 40px rgba(0,255,136,0.3)',
              margin: 0,
              letterSpacing: '4px',
              animation: 'glow 3s ease-in-out infinite',
            }}>
              SETTINGS
            </h1>
          </div>

          {/* Settings Panel */}
          <div style={{
            backgroundColor: 'rgba(0,20,10,0.85)',
            border: '2px solid #00ff88',
            width: '100%',
            boxShadow: '0 0 30px rgba(0,255,136,0.2), inset 0 0 60px rgba(0,0,0,0.5)',
          }}>
            {/* Audio Section */}
            <div style={{
              backgroundColor: '#00ff88',
              padding: '8px 15px',
            }}>
              <span style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '8px',
                color: '#001a0a',
              }}>
                ♪ AUDIO
              </span>
            </div>
            <div style={{ padding: '15px 20px' }}>
              <SliderControl 
                label="MASTER VOLUME" 
                value={settings.volume} 
                onChange={(v) => updateSetting('volume', v)} 
              />
            </div>

            {/* Display Section */}
            <div style={{
              backgroundColor: '#00ff88',
              padding: '8px 15px',
            }}>
              <span style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '8px',
                color: '#001a0a',
              }}>
                ◐ DISPLAY
              </span>
            </div>
            <div style={{ padding: '15px 20px' }}>
              <SliderControl 
                label="BRIGHTNESS" 
                value={settings.brightness} 
                onChange={(v) => updateSetting('brightness', v)} 
              />
              <SliderControl 
                label="CONTRAST" 
                value={settings.contrast} 
                onChange={(v) => updateSetting('contrast', v)} 
              />
              <SelectControl
                label="COLOR MODE"
                value={settings.colorMode}
                options={[
                  { value: 'classic', label: 'CLASSIC' },
                  { value: 'neon', label: 'NEON' },
                  { value: 'mono', label: 'MONO' },
                ]}
                onChange={(v) => updateSetting('colorMode', v)}
              />
              <ToggleControl 
                label="SCANLINES" 
                value={settings.scanlines} 
                onChange={(v) => updateSetting('scanlines', v)} 
              />
            </div>

            {/* Gameplay Section */}
            <div style={{
              backgroundColor: '#00ff88',
              padding: '8px 15px',
            }}>
              <span style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '8px',
                color: '#001a0a',
              }}>
                ▶ GAMEPLAY
              </span>
            </div>
            <div style={{ padding: '15px 20px' }}>
              <SelectControl
                label="DIFFICULTY"
                value={settings.difficulty}
                options={[
                  { value: 'easy', label: 'EASY' },
                  { value: 'normal', label: 'NORMAL' },
                  { value: 'hard', label: 'HARD' },
                ]}
                onChange={(v) => updateSetting('difficulty', v)}
              />
              <ToggleControl 
                label="SCREEN SHAKE" 
                value={settings.screenShake} 
                onChange={(v) => updateSetting('screenShake', v)} 
              />
              <ToggleControl 
                label="RUMBLE" 
                value={settings.rumble} 
                onChange={(v) => updateSetting('rumble', v)} 
              />
              <ToggleControl 
                label="AUTO-SAVE" 
                value={settings.autoSave} 
                onChange={(v) => updateSetting('autoSave', v)} 
              />
            </div>

            {/* System Section */}
            <div style={{
              backgroundColor: '#00ff88',
              padding: '8px 15px',
            }}>
              <span style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '8px',
                color: '#001a0a',
              }}>
                ◈ SYSTEM
              </span>
            </div>
            <div style={{ padding: '15px 20px' }}>
              <SelectControl
                label="LANGUAGE"
                value={settings.language}
                options={[
                  { value: 'en', label: 'EN' },
                  { value: 'jp', label: 'JP' },
                  { value: 'de', label: 'DE' },
                ]}
                onChange={(v) => updateSetting('language', v)}
              />
              <div style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                padding: '10px 0',
              }}>
                <span style={{
                  fontFamily: '"VT323", monospace',
                  fontSize: '18px',
                  color: '#00ff88',
                }}>
                  VERSION
                </span>
                <span style={{
                  fontFamily: '"VT323", monospace',
                  fontSize: '16px',
                  color: '#00aa55',
                }}>
                  v2.0.25
                </span>
              </div>
            </div>
          </div>

          {/* Action Buttons */}
          <div style={{
            display: 'flex',
            gap: '15px',
            flexWrap: 'wrap',
            justifyContent: 'center',
            marginTop: '25px',
          }}>
            {['SAVE', 'RESET', 'BACK'].map((label, idx) => (
              <button
                key={idx}
                className="pixel-btn"
                style={{
                  fontFamily: '"Press Start 2P", monospace',
                  fontSize: '10px',
                  padding: '12px 20px',
                  backgroundColor: label === 'SAVE' ? '#00ff88' : 'transparent',
                  color: label === 'SAVE' ? '#001a0a' : '#00ff88',
                  border: '2px solid #00ff88',
                  cursor: 'pointer',
                  boxShadow: '0 0 10px rgba(0,255,136,0.3)',
                  animation: 'float 3s ease-in-out infinite',
                  animationDelay: `${idx * 0.3}s`,
                }}
              >
                [{label}]
              </button>
            ))}
          </div>

          {/* Corner Decorations */}
          <div style={{
            position: 'absolute',
            top: '20px',
            left: '20px',
            width: '30px',
            height: '30px',
            borderTop: '2px solid #00ff88',
            borderLeft: '2px solid #00ff88',
            opacity: 0.5,
          }} />
          <div style={{
            position: 'absolute',
            bottom: '20px',
            right: '20px',
            width: '30px',
            height: '30px',
            borderBottom: '2px solid #00ff88',
            borderRight: '2px solid #00ff88',
            opacity: 0.5,
          }} />

          {/* Footer */}
          <div style={{
            marginTop: '20px',
            fontFamily: '"VT323", monospace',
            fontSize: '12px',
            color: '#00aa55',
            letterSpacing: '3px',
            textAlign: 'center',
          }}>
            SYS.ID: GOR-8BIT-2025 | CONFIG v1.0
          </div>
        </div>
      </div>
    </div>
  );
}
