import React, { useState, useEffect } from 'react';

const IMG_DATA = "";

export default function GorboyGameOver() {
  const [showStats, setShowStats] = useState(false);
  const [glitchText, setGlitchText] = useState(false);
  const [flickerOpacity, setFlickerOpacity] = useState(1);

  useEffect(() => {
    // Glitch effect on title
    const glitchInterval = setInterval(() => {
      setGlitchText(true);
      setTimeout(() => setGlitchText(false), 100);
    }, 3000);

    // Show stats after delay
    const statsTimeout = setTimeout(() => setShowStats(true), 800);

    // Random flicker effect
    const flickerInterval = setInterval(() => {
      setFlickerOpacity(Math.random() > 0.95 ? 0.7 : 1);
    }, 100);

    return () => {
      clearInterval(glitchInterval);
      clearTimeout(statsTimeout);
      clearInterval(flickerInterval);
    };
  }, []);

  const stats = {
    score: 127350,
    level: 12,
    time: "08:42",
    enemies: 47,
    accuracy: "82%",
    combo: 24,
  };

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: '#0a0a0a',
      fontFamily: '"Press Start 2P", "Courier New", monospace',
      overflow: 'hidden',
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&family=Silkscreen:wght@400;700&display=swap');
        
        @keyframes blink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
        
        @keyframes glowRed {
          0%, 100% { text-shadow: 0 0 10px #ff0040, 0 0 20px #ff0040, 0 0 30px #ff0040; }
          50% { text-shadow: 0 0 20px #ff0040, 0 0 40px #ff0040, 0 0 60px #ff0040, 0 0 80px #ff0040; }
        }
        
        @keyframes pulse {
          0%, 100% { opacity: 0.8; }
          50% { opacity: 1; }
        }
        
        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-5px); }
        }
        
        @keyframes gridMove {
          0% { transform: rotateX(60deg) translateY(0); }
          100% { transform: rotateX(60deg) translateY(50px); }
        }
        
        @keyframes fadeSlideUp {
          0% { opacity: 0; transform: translateY(20px); }
          100% { opacity: 1; transform: translateY(0); }
        }
        
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        
        @keyframes glitch {
          0% { transform: translate(0); }
          20% { transform: translate(-3px, 3px); }
          40% { transform: translate(3px, -3px); }
          60% { transform: translate(-3px, -3px); }
          80% { transform: translate(3px, 3px); }
          100% { transform: translate(0); }
        }
        
        @keyframes scanlineGlitch {
          0%, 100% { clip-path: inset(0 0 0 0); }
          25% { clip-path: inset(10% 0 60% 0); }
          50% { clip-path: inset(40% 0 20% 0); }
          75% { clip-path: inset(80% 0 5% 0); }
        }
        
        @keyframes colorShift {
          0%, 100% { filter: hue-rotate(0deg); }
          50% { filter: hue-rotate(-20deg); }
        }
        
        .scanlines::before {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: repeating-linear-gradient(
            0deg,
            rgba(0, 0, 0, 0.15) 0px,
            rgba(0, 0, 0, 0.15) 1px,
            transparent 1px,
            transparent 2px
          );
          pointer-events: none;
          z-index: 10;
        }
        
        .perspective-grid-container {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          height: 60%;
          perspective: 400px;
          perspective-origin: 50% 0%;
          overflow: hidden;
          mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
          -webkit-mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
        }
        
        .perspective-grid {
          position: absolute;
          top: 0;
          left: -50%;
          width: 200%;
          height: 300%;
          background-image: 
            linear-gradient(rgba(255,0,64,0.3) 2px, transparent 2px),
            linear-gradient(90deg, rgba(255,0,64,0.3) 2px, transparent 2px);
          background-size: 50px 50px;
          transform-origin: center top;
          animation: gridMove 2s linear infinite;
        }
        
        .horizon-glow {
          position: absolute;
          bottom: 40%;
          left: 0;
          right: 0;
          height: 200px;
          background: radial-gradient(ellipse 80% 50% at 50% 100%, rgba(255,0,64,0.2) 0%, transparent 70%);
          pointer-events: none;
        }
        
        .pixel-btn {
          image-rendering: pixelated;
          transition: all 0.1s ease;
        }
        
        .pixel-btn:hover {
          transform: scale(1.05);
          filter: brightness(1.2);
        }
        
        .pixel-btn:active {
          transform: scale(0.95);
        }
        
        .stat-row {
          animation: fadeSlideUp 0.5s ease-out forwards;
          opacity: 0;
        }
        
        .glitch-text {
          animation: glitch 0.1s linear, colorShift 0.1s linear;
        }
        
        .skull {
          animation: pulse 2s ease-in-out infinite;
        }
      `}</style>

      <div style={{
        position: 'relative',
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #0a0a0a 0%, #1a0a0a 40%, #200a0a 100%)',
        overflow: 'hidden',
        opacity: flickerOpacity,
        transition: 'opacity 0.05s',
      }} className="scanlines">
        
        {/* 3D Perspective Grid - Red tinted */}
        <div className="perspective-grid-container">
          <div className="perspective-grid" />
        </div>
        
        {/* Horizon Glow - Red */}
        <div className="horizon-glow" />
        
        {/* Background Image */}
        <div style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          width: '100%',
          maxWidth: '600px',
          opacity: 0.2,
          mixBlendMode: 'lighten',
          filter: 'hue-rotate(-60deg)',
        }}>
          <img 
            src={`data:image/webp;base64,${IMG_DATA}`}
            alt="GORBOY Dark"
            style={{ width: '100%', height: 'auto', mixBlendMode: 'lighten' }}
          />
        </div>
        
        {/* Main Content */}
        <div style={{
          position: 'relative',
          zIndex: 5,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          padding: '40px 20px',
          maxWidth: '500px',
          margin: '0 auto',
        }}>
          
          {/* Skull Icon */}
          <div className="skull" style={{
            fontSize: '48px',
            marginBottom: '10px',
            filter: 'drop-shadow(0 0 10px #ff0040)',
          }}>
            💀
          </div>

          {/* Game Over Title */}
          <h1 
            className={glitchText ? 'glitch-text' : ''}
            style={{
              fontFamily: '"Press Start 2P", monospace',
              fontSize: 'clamp(28px, 8vw, 48px)',
              color: '#ff0040',
              textShadow: '0 0 20px rgba(255,0,64,0.5), 0 0 40px rgba(255,0,64,0.3)',
              margin: 0,
              marginBottom: '10px',
              letterSpacing: '4px',
              animation: 'glowRed 2s ease-in-out infinite',
              textAlign: 'center',
            }}
          >
            GAME OVER
          </h1>
          
          <div style={{
            fontFamily: '"VT323", monospace',
            fontSize: '18px',
            color: '#ff6b6b',
            marginBottom: '30px',
            letterSpacing: '4px',
          }}>
            ■ MISSION FAILED ■
          </div>

          {/* Stats Panel */}
          <div style={{
            backgroundColor: 'rgba(20,5,5,0.9)',
            border: '2px solid #ff0040',
            width: '100%',
            boxShadow: '0 0 30px rgba(255,0,64,0.2), inset 0 0 60px rgba(0,0,0,0.5)',
            marginBottom: '25px',
          }}>
            {/* Header */}
            <div style={{
              backgroundColor: '#ff0040',
              padding: '10px 15px',
            }}>
              <span style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '10px',
                color: '#0a0a0a',
              }}>
                ▶ FINAL STATS
              </span>
            </div>
            
            {/* Stats */}
            <div style={{ padding: '15px 20px' }}>
              {showStats && Object.entries({
                'SCORE': stats.score.toLocaleString(),
                'LEVEL': stats.level,
                'TIME': stats.time,
                'ENEMIES': stats.enemies,
                'ACCURACY': stats.accuracy,
                'MAX COMBO': stats.combo,
              }).map(([label, value], idx) => (
                <div
                  key={label}
                  className="stat-row"
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '10px 0',
                    borderBottom: idx < 5 ? '1px solid rgba(255,0,64,0.3)' : 'none',
                    animationDelay: `${idx * 0.1}s`,
                  }}
                >
                  <span style={{
                    fontFamily: '"VT323", monospace',
                    fontSize: '18px',
                    color: '#ff6b6b',
                  }}>
                    {label}
                  </span>
                  <span style={{
                    fontFamily: '"VT323", monospace',
                    fontSize: '22px',
                    color: label === 'SCORE' ? '#ff0040' : '#ff6b6b',
                    textShadow: label === 'SCORE' ? '0 0 10px rgba(255,0,64,0.5)' : 'none',
                  }}>
                    {value}
                  </span>
                </div>
              ))}
            </div>

            {/* New High Score? */}
            <div style={{
              borderTop: '2px solid #ff0040',
              padding: '15px',
              backgroundColor: 'rgba(255,0,64,0.1)',
              textAlign: 'center',
            }}>
              <span style={{
                fontFamily: '"Press Start 2P", monospace',
                fontSize: '10px',
                color: '#ff6b6b',
                animation: 'blink 1s infinite',
              }}>
                ★ NEW HIGH SCORE! ★
              </span>
            </div>
          </div>

          {/* Insert Coin */}
          <div style={{
            fontFamily: '"VT323", monospace',
            fontSize: '20px',
            color: '#ff0040',
            marginBottom: '20px',
            animation: 'blink 1.5s infinite',
          }}>
            INSERT COIN TO CONTINUE
          </div>

          {/* Countdown */}
          <div style={{
            fontFamily: '"Press Start 2P", monospace',
            fontSize: '24px',
            color: '#ff6b6b',
            marginBottom: '25px',
          }}>
            9
          </div>

          {/* Action Buttons */}
          <div style={{
            display: 'flex',
            gap: '15px',
            flexWrap: 'wrap',
            justifyContent: 'center',
          }}>
            {['RETRY', 'SCORES', 'QUIT'].map((label, idx) => (
              <button
                key={idx}
                className="pixel-btn"
                style={{
                  fontFamily: '"Press Start 2P", monospace',
                  fontSize: '10px',
                  padding: '12px 20px',
                  backgroundColor: label === 'RETRY' ? '#ff0040' : 'transparent',
                  color: label === 'RETRY' ? '#0a0a0a' : '#ff0040',
                  border: '2px solid #ff0040',
                  cursor: 'pointer',
                  boxShadow: '0 0 10px rgba(255,0,64,0.3)',
                  animation: 'float 3s ease-in-out infinite',
                  animationDelay: `${idx * 0.3}s`,
                }}
              >
                [{label}]
              </button>
            ))}
          </div>

          {/* Corner Decorations */}
          <div style={{
            position: 'absolute',
            top: '20px',
            left: '20px',
            width: '30px',
            height: '30px',
            borderTop: '2px solid #ff0040',
            borderLeft: '2px solid #ff0040',
            opacity: 0.5,
          }} />
          <div style={{
            position: 'absolute',
            bottom: '20px',
            right: '20px',
            width: '30px',
            height: '30px',
            borderBottom: '2px solid #ff0040',
            borderRight: '2px solid #ff0040',
            opacity: 0.5,
          }} />

          {/* Footer */}
          <div style={{
            marginTop: '30px',
            fontFamily: '"VT323", monospace',
            fontSize: '12px',
            color: '#ff6b6b',
            letterSpacing: '3px',
            textAlign: 'center',
            opacity: 0.7,
          }}>
            SYS.ID: GOR-8BIT-2025 | STATUS: TERMINATED
          </div>
        </div>
      </div>
    </div>
  );
}
