import React, { useState } from 'react';

const IMG_DATA = "";

export default function GorboyControls() {
  const [activeTab, setActiveTab] = useState('keyboard');

  const Arrow = ({ direction, color = '#001a0a' }) => {
    const rotations = { up: '0deg', down: '180deg', left: '-90deg', right: '90deg' };
    return (
      <div style={{
        width: 0,
        height: 0,
        borderLeft: '8px solid transparent',
        borderRight: '8px solid transparent',
        borderBottom: `12px solid ${color}`,
        transform: `rotate(${rotations[direction]})`,
      }} />
    );
  };

  const KeyCap = ({ label, size = 'normal', active = false, arrow = null }) => {
    const widths = { normal: '45px', wide: '70px', space: '180px' };
    return (
      <div style={{
        width: widths[size],
        height: '45px',
        backgroundColor: active ? '#00ff88' : 'rgba(0,30,15,0.9)',
        border: '2px solid ' + (active ? '#00ff88' : '#00aa55'),
        borderRadius: '4px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily: '"Press Start 2P", monospace',
        fontSize: size === 'space' ? '8px' : '10px',
        color: active ? '#001a0a' : '#00ff88',
        boxShadow: active 
          ? '0 0 15px rgba(0,255,136,0.6), inset 0 -3px 0 rgba(0,0,0,0.3)' 
          : '0 4px 0 #001a0a, inset 0 -3px 0 rgba(0,0,0,0.3)',
        transition: 'all 0.1s ease',
        cursor: 'pointer',
        userSelect: 'none',
      }}>
        {arrow ? <Arrow direction={arrow} color={active ? '#001a0a' : '#00ff88'} /> : label}
      </div>
    );
  };

  const ControlMapping = ({ keys, action }) => (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      padding: '12px 0',
      borderBottom: '1px solid rgba(0,255,136,0.2)',
    }}>
      <div style={{ display: 'flex', gap: '8px' }}>
        {keys.map((key, idx) => (
          <span key={idx} style={{
            fontFamily: '"Press Start 2P", monospace',
            fontSize: '10px',
            color: '#00ff88',
            backgroundColor: 'rgba(0,255,136,0.15)',
            padding: '6px 10px',
            border: '1px solid #00aa55',
          }}>
            {key}
          </span>
        ))}
      </div>
      <span style={{
        fontFamily: '"VT323", monospace',
        fontSize: '18px',
        color: '#00aa55',
      }}>
        {action}
      </span>
    </div>
  );

  const MobileArrow = ({ direction, color = '#00ff88' }) => {
    const rotations = { up: '0deg', down: '180deg', left: '-90deg', right: '90deg' };
    return (
      <div style={{
        width: 0,
        height: 0,
        borderLeft: '6px solid transparent',
        borderRight: '6px solid transparent',
        borderBottom: `10px solid ${color}`,
        transform: `rotate(${rotations[direction]})`,
      }} />
    );
  };

  const MobileButton = ({ label, size = 50, round = false, color = '#00ff88', arrow = null }) => (
    <div style={{
      width: size,
      height: size,
      backgroundColor: 'rgba(0,30,15,0.9)',
      border: `3px solid ${color}`,
      borderRadius: round ? '50%' : '8px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontFamily: '"Press Start 2P", monospace',
      fontSize: round ? '12px' : '8px',
      color: color,
      boxShadow: `0 0 10px ${color}40, inset 0 0 20px rgba(0,0,0,0.5)`,
    }}>
      {arrow ? <MobileArrow direction={arrow} color={color} /> : label}
    </div>
  );

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: '#0a0a0a',
      fontFamily: '"Press Start 2P", "Courier New", monospace',
      overflow: 'hidden',
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&family=Silkscreen:wght@400;700&display=swap');
        
        @keyframes blink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
        
        @keyframes glow {
          0%, 100% { text-shadow: 0 0 10px currentColor, 0 0 20px currentColor; }
          50% { text-shadow: 0 0 20px currentColor, 0 0 40px currentColor, 0 0 60px currentColor; }
        }
        
        @keyframes float {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-5px); }
        }
        
        @keyframes gridMove {
          0% { transform: rotateX(60deg) translateY(0); }
          100% { transform: rotateX(60deg) translateY(50px); }
        }
        
        @keyframes pulse {
          0%, 100% { opacity: 0.6; }
          50% { opacity: 1; }
        }
        
        .scanlines::before {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: repeating-linear-gradient(
            0deg,
            rgba(0, 0, 0, 0.1) 0px,
            rgba(0, 0, 0, 0.1) 1px,
            transparent 1px,
            transparent 2px
          );
          pointer-events: none;
          z-index: 10;
        }
        
        .perspective-grid-container {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          height: 60%;
          perspective: 400px;
          perspective-origin: 50% 0%;
          overflow: hidden;
          mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
          -webkit-mask-image: linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0.8) 40%, rgba(0,0,0,0) 100%);
        }
        
        .perspective-grid {
          position: absolute;
          top: 0;
          left: -50%;
          width: 200%;
          height: 300%;
          background-image: 
            linear-gradient(rgba(0,255,136,0.4) 2px, transparent 2px),
            linear-gradient(90deg, rgba(0,255,136,0.4) 2px, transparent 2px);
          background-size: 50px 50px;
          transform-origin: center top;
          animation: gridMove 2s linear infinite;
        }
        
        .horizon-glow {
          position: absolute;
          bottom: 40%;
          left: 0;
          right: 0;
          height: 200px;
          background: radial-gradient(ellipse 80% 50% at 50% 100%, rgba(0,255,136,0.15) 0%, transparent 70%);
          pointer-events: none;
        }
        
        .pixel-btn {
          image-rendering: pixelated;
          transition: all 0.1s ease;
        }
        
        .pixel-btn:hover {
          transform: scale(1.05);
          filter: brightness(1.2);
        }
        
        .pixel-btn:active {
          transform: scale(0.95);
        }
        
        .tab-btn {
          transition: all 0.15s ease;
        }
        
        .tab-btn:hover {
          filter: brightness(1.1);
        }
      `}</style>

      <div style={{
        position: 'relative',
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #0a0a0a 0%, #0a1a0f 40%, #0f2a1a 100%)',
        overflow: 'hidden',
      }} className="scanlines">
        
        {/* 3D Perspective Grid */}
        <div className="perspective-grid-container">
          <div className="perspective-grid" />
        </div>
        
        {/* Horizon Glow */}
        <div className="horizon-glow" />
        
        {/* Background Image */}
        <div style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          width: '100%',
          maxWidth: '600px',
          opacity: 0.35,
          mixBlendMode: 'lighten',
        }}>
          <img 
            src={`data:image/webp;base64,${IMG_DATA}`}
            alt="GORBOY Dark"
            style={{ width: '100%', height: 'auto', mixBlendMode: 'lighten' }}
          />
        </div>
        
        {/* Main Content */}
        <div style={{
          position: 'relative',
          zIndex: 5,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          padding: '30px 20px',
          maxWidth: '550px',
          margin: '0 auto',
        }}>
          {/* Header */}
          <div style={{
            textAlign: 'center',
            marginBottom: '20px',
          }}>
            <div style={{
              fontFamily: '"VT323", monospace',
              fontSize: '14px',
              color: '#00ff88',
              letterSpacing: '12px',
              marginBottom: '8px',
              opacity: 0.7,
            }}>
              GORBOY://INPUT
            </div>
            <h1 style={{
              fontFamily: '"Press Start 2P", monospace',
              fontSize: 'clamp(20px, 5vw, 32px)',
              color: '#00ff88',
              textShadow: '0 0 20px rgba(0,255,136,0.5), 0 0 40px rgba(0,255,136,0.3)',
              margin: 0,
              letterSpacing: '4px',
              animation: 'glow 3s ease-in-out infinite',
            }}>
              CONTROLS
            </h1>
          </div>

          {/* Tab Switcher */}
          <div style={{
            display: 'flex',
            gap: '0',
            marginBottom: '20px',
            border: '2px solid #00ff88',
          }}>
            {[
              { id: 'keyboard', label: '⌨ KEYBOARD', icon: '⌨' },
              { id: 'mobile', label: '📱 TOUCH', icon: '📱' },
            ].map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className="tab-btn"
                style={{
                  fontFamily: '"Press Start 2P", monospace',
                  fontSize: '9px',
                  padding: '12px 20px',
                  backgroundColor: activeTab === tab.id ? '#00ff88' : 'transparent',
                  color: activeTab === tab.id ? '#001a0a' : '#00aa55',
                  border: 'none',
                  cursor: 'pointer',
                }}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {/* Controls Panel */}
          <div style={{
            backgroundColor: 'rgba(0,20,10,0.85)',
            border: '2px solid #00ff88',
            width: '100%',
            boxShadow: '0 0 30px rgba(0,255,136,0.2), inset 0 0 60px rgba(0,0,0,0.5)',
          }}>
            
            {activeTab === 'keyboard' && (
              <>
                {/* Keyboard Visual */}
                <div style={{
                  padding: '25px 20px',
                  borderBottom: '2px solid #00ff88',
                }}>
                  <div style={{
                    fontFamily: '"VT323", monospace',
                    fontSize: '16px',
                    color: '#00aa55',
                    marginBottom: '20px',
                    textAlign: 'center',
                  }}>
                    &gt; MOVEMENT KEYS
                  </div>
                  
                  {/* Arrow Keys / WASD Display */}
                  <div style={{
                    display: 'flex',
                    justifyContent: 'center',
                    gap: '40px',
                  }}>
                    {/* WASD */}
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '5px' }}>
                      <KeyCap label="W" active />
                      <div style={{ display: 'flex', gap: '5px' }}>
                        <KeyCap label="A" active />
                        <KeyCap label="S" active />
                        <KeyCap label="D" active />
                      </div>
                      <div style={{
                        fontFamily: '"VT323", monospace',
                        fontSize: '14px',
                        color: '#00aa55',
                        marginTop: '8px',
                      }}>
                        WASD
                      </div>
                    </div>

                    <div style={{
                      fontFamily: '"VT323", monospace',
                      fontSize: '20px',
                      color: '#00ff88',
                      alignSelf: 'center',
                    }}>
                      OR
                    </div>

                    {/* Arrow Keys */}
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '5px' }}>
                      <KeyCap arrow="up" active />
                      <div style={{ display: 'flex', gap: '5px' }}>
                        <KeyCap arrow="left" active />
                        <KeyCap arrow="down" active />
                        <KeyCap arrow="right" active />
                      </div>
                      <div style={{
                        fontFamily: '"VT323", monospace',
                        fontSize: '14px',
                        color: '#00aa55',
                        marginTop: '8px',
                      }}>
                        ARROWS
                      </div>
                    </div>
                  </div>
                </div>

                {/* Key Mappings */}
                <div style={{
                  backgroundColor: '#00ff88',
                  padding: '8px 15px',
                }}>
                  <span style={{
                    fontFamily: '"Press Start 2P", monospace',
                    fontSize: '8px',
                    color: '#001a0a',
                  }}>
                    ▶ ACTION KEYS
                  </span>
                </div>
                <div style={{ padding: '10px 20px' }}>
                  <ControlMapping keys={['Z', 'J']} action="CONFIRM / ACTION" />
                  <ControlMapping keys={['X', 'K']} action="CANCEL / BACK" />
                  <ControlMapping keys={['ENTER']} action="START / PAUSE" />
                  <ControlMapping keys={['SHIFT']} action="SELECT" />
                  <ControlMapping keys={['SPACE']} action="JUMP / SPECIAL" />
                  <ControlMapping keys={['ESC']} action="MENU" />
                </div>
              </>
            )}

            {activeTab === 'mobile' && (
              <>
                {/* Mobile Visual */}
                <div style={{
                  padding: '25px 20px',
                  borderBottom: '2px solid #00ff88',
                }}>
                  <div style={{
                    fontFamily: '"VT323", monospace',
                    fontSize: '16px',
                    color: '#00aa55',
                    marginBottom: '25px',
                    textAlign: 'center',
                  }}>
                    &gt; VIRTUAL GAMEPAD
                  </div>
                  
                  {/* Mobile Controller Layout */}
                  <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '0 10px',
                  }}>
                    {/* D-Pad */}
                    <div style={{
                      position: 'relative',
                      width: '120px',
                      height: '120px',
                    }}>
                      <div style={{ position: 'absolute', top: '0', left: '50%', transform: 'translateX(-50%)' }}>
                        <MobileButton arrow="up" size={40} />
                      </div>
                      <div style={{ position: 'absolute', bottom: '0', left: '50%', transform: 'translateX(-50%)' }}>
                        <MobileButton arrow="down" size={40} />
                      </div>
                      <div style={{ position: 'absolute', left: '0', top: '50%', transform: 'translateY(-50%)' }}>
                        <MobileButton arrow="left" size={40} />
                      </div>
                      <div style={{ position: 'absolute', right: '0', top: '50%', transform: 'translateY(-50%)' }}>
                        <MobileButton arrow="right" size={40} />
                      </div>
                      <div style={{
                        position: 'absolute',
                        top: '50%',
                        left: '50%',
                        transform: 'translate(-50%, -50%)',
                        width: '30px',
                        height: '30px',
                        backgroundColor: '#001a0a',
                        border: '2px solid #00aa55',
                      }} />
                    </div>

                    {/* Center buttons */}
                    <div style={{
                      display: 'flex',
                      flexDirection: 'column',
                      gap: '10px',
                    }}>
                      <div style={{
                        width: '50px',
                        height: '20px',
                        backgroundColor: 'rgba(0,30,15,0.9)',
                        border: '2px solid #00aa55',
                        borderRadius: '10px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontFamily: '"Press Start 2P", monospace',
                        fontSize: '5px',
                        color: '#00aa55',
                      }}>
                        SELECT
                      </div>
                      <div style={{
                        width: '50px',
                        height: '20px',
                        backgroundColor: 'rgba(0,30,15,0.9)',
                        border: '2px solid #00aa55',
                        borderRadius: '10px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontFamily: '"Press Start 2P", monospace',
                        fontSize: '5px',
                        color: '#00aa55',
                      }}>
                        START
                      </div>
                    </div>

                    {/* Action Buttons */}
                    <div style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '15px',
                    }}>
                      <div style={{ marginTop: '30px' }}>
                        <MobileButton label="B" size={55} round color="#ffd93d" />
                      </div>
                      <div style={{ marginTop: '-10px' }}>
                        <MobileButton label="A" size={55} round color="#ff6b6b" />
                      </div>
                    </div>
                  </div>
                </div>

                {/* Touch Mappings */}
                <div style={{
                  backgroundColor: '#00ff88',
                  padding: '8px 15px',
                }}>
                  <span style={{
                    fontFamily: '"Press Start 2P", monospace',
                    fontSize: '8px',
                    color: '#001a0a',
                  }}>
                    ▶ TOUCH ACTIONS
                  </span>
                </div>
                <div style={{ padding: '10px 20px' }}>
                  <ControlMapping keys={['D-PAD']} action="MOVEMENT" />
                  <ControlMapping keys={['A']} action="CONFIRM / ACTION" />
                  <ControlMapping keys={['B']} action="CANCEL / BACK" />
                  <ControlMapping keys={['START']} action="PAUSE / MENU" />
                  <ControlMapping keys={['SELECT']} action="INVENTORY" />
                  <ControlMapping keys={['2-TAP']} action="QUICK MENU" />
                </div>
              </>
            )}
          </div>

          {/* Pro Tips */}
          <div style={{
            marginTop: '20px',
            padding: '15px',
            backgroundColor: 'rgba(0,20,10,0.7)',
            border: '1px solid #00aa55',
            width: '100%',
          }}>
            <div style={{
              fontFamily: '"VT323", monospace',
              fontSize: '14px',
              color: '#00ff88',
              marginBottom: '8px',
            }}>
              💡 PRO TIP:
            </div>
            <div style={{
              fontFamily: '"VT323", monospace',
              fontSize: '16px',
              color: '#00aa55',
            }}>
              {activeTab === 'keyboard' 
                ? 'Hold SHIFT + direction for precision movement!'
                : 'Swipe from screen edge for quick inventory access!'
              }
            </div>
          </div>

          {/* Action Buttons */}
          <div style={{
            display: 'flex',
            gap: '15px',
            flexWrap: 'wrap',
            justifyContent: 'center',
            marginTop: '20px',
          }}>
            {['REMAP', 'RESET', 'BACK'].map((label, idx) => (
              <button
                key={idx}
                className="pixel-btn"
                style={{
                  fontFamily: '"Press Start 2P", monospace',
                  fontSize: '10px',
                  padding: '12px 20px',
                  backgroundColor: 'transparent',
                  color: '#00ff88',
                  border: '2px solid #00ff88',
                  cursor: 'pointer',
                  boxShadow: '0 0 10px rgba(0,255,136,0.3)',
                  animation: 'float 3s ease-in-out infinite',
                  animationDelay: `${idx * 0.3}s`,
                }}
              >
                [{label}]
              </button>
            ))}
          </div>

          {/* Corner Decorations */}
          <div style={{
            position: 'absolute',
            top: '20px',
            left: '20px',
            width: '30px',
            height: '30px',
            borderTop: '2px solid #00ff88',
            borderLeft: '2px solid #00ff88',
            opacity: 0.5,
          }} />
          <div style={{
            position: 'absolute',
            bottom: '20px',
            right: '20px',
            width: '30px',
            height: '30px',
            borderBottom: '2px solid #00ff88',
            borderRight: '2px solid #00ff88',
            opacity: 0.5,
          }} />

          {/* Footer */}
          <div style={{
            marginTop: '20px',
            fontFamily: '"VT323", monospace',
            fontSize: '12px',
            color: '#00aa55',
            letterSpacing: '3px',
            textAlign: 'center',
          }}>
            SYS.ID: GOR-8BIT-2025 | INPUT v1.0
          </div>
        </div>
      </div>
    </div>
  );
}
